function LessonCard({ status, title }) {
 // Pattern 1: if-else outside (for early return)
 if (status === 'locked') {
 return <div>🔒 {title} - Locked - Complete previous lesson</div>;
 }

 return (
 <div>
 <h3>{title}</h3>
 {/* Pattern 2: Ternary? : for if-else inside JSX */}
 <span style={{color: status==='completed'? 'green' : 'blue'}}>
 {status==='completed'? '✓ Completed' : '▶ Current'}
 </span>

 {/* Pattern 3: && for conditional show (only if true, show) */}
 {status==='current' && <button>Start Lesson</button>}
 {status==='completed' && <button>Review Again</button>}

 {/* Pattern 4: Switch logic via object map for many statuses */}
 {(() => {
 const badge = {
 completed: <span>✅</span>,
 current: <span>▶️</span>,
 locked: <span>🔒</span>
 };
 return badge[status];
 })()}
 </div>
 );
}

function StatusBadge({ status }) {
 if (status === 'completed') {
 return <span style={{background: 'rgba(34,197,94,0.14)', color: '#4ade80', padding: '5px 10px', borderRadius: '999px'}}>COMPLETED</span>;
 }
 if (status === 'current') {
 return <span style={{background: 'rgba(97,218,251,0.14)', color: '#61dafb', padding: '5px 10px', borderRadius: '999px'}}>CURRENT</span>;
 }
 return <span style={{background: 'rgba(148,163,184,0.14)', color: '#94a3b8', padding: '5px 10px', borderRadius: '999px'}}>LOCKED</span>;
}

