function LessonGrid({ lessons, loading, error, search }) {
 // State 1: Loading
 if (loading) {
 return <div style={{textAlign: 'center', padding: '40px'}}>Loading your course... spinner</div>;
 }

 // State 2: Error
 if (error) {
 return <div style={{color: 'red', padding: '20px'}}>Failed to load: {error} <button>Retry</button></div>;
 }

 // State 3: Empty (no lessons at all)
 if (lessons.length === 0) {
 return <div style={{textAlign: 'center', padding: '40px'}}><p>No lessons yet</p><button>+ Add First Lesson</button></div>;
 }

 // Filter for search
 const filtered = lessons.filter(l => l.title.toLowerCase().includes(search.toLowerCase()));

 // State 4: No Results (search matches 0)
 if (filtered.length === 0) {
 return <div style={{textAlign: 'center', padding: '40px'}}><p>No lessons match "{search}"</p><p>Try different search</p></div>;
 }

 // State 5: Happy path - show list
 return (
 <div style={{display: 'grid', gap: '12px'}}>
 {filtered.map(lesson => <p key={lesson.id}>{lesson.title}</p>)}
 </div>
 );
}

import { useState } from 'react';

function LessonDashboard() {
 const [lessons] = useState([
 {id: 1, title: "Introduction", status: "completed", xp: 100},
 {id: 2, title: "JSX", status: "completed", xp: 100},
 {id: 3, title: "Props", status: "current", xp: 50},
 {id: 4, title: "State", status: "locked", xp: 0},
 ]);
 const [filter, setFilter] = useState("all");
 const [sortBy, setSortBy] = useState("id");

 // Filter
 const filtered = lessons.filter(l => filter==="all" || l.status===filter);

 // Sort
 const sorted = [...filtered].sort((a,b) => {
 if (sortBy==="title") return a.title.localeCompare(b.title);
 if (sortBy==="xp") return b.xp - a.xp;
 return a.id - b.id;
 });

 return (
 <div>
 <div style={{display: 'flex', gap: '10px'}}>
 <select value={filter} onChange={(e) => setFilter(e.target.value)}><option value="all">All</option><option value="completed">Completed</option></select>
 <select value={sortBy} onChange={(e) => setSortBy(e.target.value)}><option value="id">Sort by ID</option><option value="title">Sort by Title</option></select>
 </div>
 <p>Showing {sorted.length} lessons</p>
 {sorted.map(l => <p key={l.id}>{l.id}: {l.title} - {l.status} - {l.xp} XP</p>)}
 </div>
 );
}
