import { useState, useEffect } from 'react';

function App() {
 const [lessons, setLessons] = useState([]);
 const [loading, setLoading] = useState(true);
 const [search, setSearch] = useState("");
 const [filter, setFilter] = useState("all");
 const [sortBy, setSortBy] = useState("id");

 useEffect(() => {
 setTimeout(() => {
 setLessons([
 {id: 1, title: "Introduction to React", status: "completed", xp: 100},
 {id: 2, title: "JSX and Components", status: "completed", xp: 100},
 {id: 3, title: "Props and Communication", status: "current", xp: 50},
 {id: 4, title: "State and Interaction", status: "locked", xp: 0},
 {id: 5, title: "React Hooks", status: "locked", xp: 0},
 ]);
 setLoading(false);
 }, 1000);
 }, []);

 const filtered = lessons.filter(l => {
 const matchSearch = l.title.toLowerCase().includes(search.toLowerCase());
 const matchFilter = filter==="all" || l.status===filter;
 return matchSearch && matchFilter;
 });

 const sorted = [...filtered].sort((a,b) => sortBy==="title"? a.title.localeCompare(b.title) : a.id - b.id);

 function getBadge(status) {
 if (status==="completed") return <span style={{background: '#22c55e20', color: '#4ade80', padding: '4px 8px', borderRadius: '99px', fontSize: '10px'}}>COMPLETED</span>;
 if (status==="current") return <span style={{background: '#61dafb20', color: '#61dafb', padding: '4px 8px', borderRadius: '99px', fontSize: '10px'}}>CURRENT</span>;
 return <span style={{background: '#94a3b820', color: '#94a3b8', padding: '4px 8px', borderRadius: '99px', fontSize: '10px'}}>LOCKED</span>;
 }

 if (loading) return <div style={{padding: '40px', textAlign: 'center', background: '#07111f', color: 'white', minHeight: '100vh'}}>Loading your course... spinner (useEffect fetch)</div>;
 if (lessons.length===0) return <div style={{padding: '40px', textAlign: 'center'}}>No lessons yet <button>+ Add First</button></div>;

 return (
 <div style={{background: '#07111f', color: 'white', minHeight: '100vh', padding: '20px'}}>
 <h2>React Development - {lessons.filter(l => l.status==='completed').length}/{lessons.length} completed</h2>
 <div style={{display: 'flex', gap: '10px', margin: '15px 0', flexWrap: 'wrap'}}>
 <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search lessons..." style={{padding: '8px', flex: 1, minWidth: '200px'}} />
 <select value={filter} onChange={(e) => setFilter(e.target.value)} style={{padding: '8px'}}><option value="all">All</option><option value="completed">Completed</option><option value="current">Current</option><option value="locked">Locked</option></select>
 <select value={sortBy} onChange={(e) => setSortBy(e.target.value)} style={{padding: '8px'}}><option value="id">Sort by ID</option><option value="title">Sort by Title</option></select>
 </div>
 {sorted.length===0? (
 <div style={{textAlign: 'center', padding: '40px', color: '#94a3b8'}}><p>No lessons match "{search}" with filter "{filter}"</p><button onClick={() => {setSearch(""); setFilter("all");}}>Clear Filters</button></div>
 ) : (
 <div style={{display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '16px'}}>
 {sorted.map(lesson => (
 <div key={lesson.id} style={{background: 'rgba(15,31,51,0.88)', border: '1px solid rgba(97,218,251,0.16)', borderRadius: '20px', padding: '20px'}}>
 <div style={{display: 'flex', justifyContent: 'space-between'}}><span style={{color: '#61dafb', fontSize: '11px'}}>LESSON {String(lesson.id).padStart(2,'0')}</span>{getBadge(lesson.status)}</div>
 <h3 style={{margin: '10px 0'}}>{lesson.title}</h3>
 <p style={{color: '#94a3b8', fontSize: '13px'}}>{lesson.xp} XP</p>
 {lesson.status!== 'locked' && <button style={{marginTop: '10px', padding: '8px 12px', background: '#61dafb', border: 'none', borderRadius: '8px', fontWeight: '700'}}>Start →</button>}
 </div>
 ))}
 </div>
 )}
 </div>
 );
}
export default App;
